/**
 * @file    luxcal.js
 * @version 260319A
 * @date    2026-03-19
 *
 * Kwal - Lux Calibration module
 * Calibration panel for lux → brightness curve fitting
 * API: POST /api/lux/calibrate, /api/lux/sample, /api/lux/status,
 *       /api/lux/fit, /api/lux/clear, /api/lux/reload, GET /api/lux/csv
 */
Kwal.luxcal = (function() {
  'use strict';

  var sampleBtn, approveBtn, clearBtn, resetBtn, downloadBtn, acceptBtn;
  var statusEl, luxValueEl, brightnessValueEl, fitResultEl;
  var newFitEl, newParamsEl;
  var briSlider, briLabel;
  var chartCanvas;
  var savedBrightness = -1;  // brightness before modal open (-1 = not saved)
  var hasLuxSensor = true;   // assume present until status says otherwise

  // Quadratic slider mapping: more resolution at low brightness
  function sliderToBrightness(v) { return Math.round(v * v / 100); }
  function brightnessToSlider(b) { return Math.round(Math.sqrt(b * 100)); }

  function formatParams(d) {
    var s = 'brMax=' + (d.brMax != null ? Number(d.brMax).toFixed(1) : '?') +
           ' slope=' + (d.luxRate != null ? Number(d.luxRate).toFixed(4) : '?');
    if (d.luxMax != null) s += ' (lux 0-' + Number(d.luxMax).toFixed(0) + ')';
    return s;
  }

  function setStatus(text) {
    if (statusEl) statusEl.textContent = text;
  }

  function hideAccept() {
    if (newFitEl) newFitEl.style.display = 'none';
  }

  var lastFitParams = null;

  function setDisabledAll(disabled) {
    if (sampleBtn)   sampleBtn.disabled = disabled;
    if (briSlider)   briSlider.disabled = disabled;
  }

  function updateUI(data) {
    if (!data) return;
    if (typeof data.lastLux === 'number' && luxValueEl) {
      luxValueEl.textContent = data.lastLux.toFixed(1);
    }
    if (typeof data.lastBrightness === 'number' && brightnessValueEl) {
      brightnessValueEl.textContent = data.lastBrightness.toFixed(1);
    }
  }

  function loadStatus() {
    // Save current brightness and sync cal slider
    var mainSlider = document.getElementById('brightness');
    if (mainSlider && briSlider && briLabel) {
      savedBrightness = parseInt(mainSlider.value, 10);
      briSlider.value = brightnessToSlider(savedBrightness);
      briLabel.textContent = savedBrightness + '%';
    }
    fetch('/api/lux/status').then(function(r) { return r.json(); })
      .then(function(data) {
        hasLuxSensor = !!data.hasLuxSensor;
        if (!hasLuxSensor) {
          setDisabledAll(true);
          setStatus('Geen lux sensor');
          return;
        }
        updateUI(data);
        // Show current params
        if (fitResultEl && typeof data.brMax === 'number') {
          fitResultEl.textContent = 'Huidig: ' + formatParams(data);
        }
        hideAccept();
        // Auto-enable calibration mode on modal open
        fetch('/api/lux/calibrate?mode=on', { method: 'POST' })
          .then(function(r) { return r.json(); })
          .then(function(d) {
            updateUI(d);
            if (sampleBtn) sampleBtn.disabled = false;
            fetchAndDraw();
          })
          .catch(function() { setStatus('Calibratie activeren mislukt'); });
      })
      .catch(function() { setStatus('Status ophalen mislukt'); });
  }

  function onModalClose() {
    // Restore brightness to value before modal was opened
    if (savedBrightness >= 0) {
      fetch('/setBrightness?value=' + savedBrightness, { method: 'POST' }).catch(function() {});
      var mainSlider = document.getElementById('brightness');
      var mainLabel = document.getElementById('bri-num');
      if (mainSlider) mainSlider.value = savedBrightness;
      if (mainLabel) mainLabel.textContent = savedBrightness + '%';
      if (briSlider) briSlider.value = brightnessToSlider(savedBrightness);
      if (briLabel) briLabel.textContent = savedBrightness + '%';
      savedBrightness = -1;
    }
    // Auto-disable calibration mode on modal close
    fetch('/api/lux/calibrate?mode=off', { method: 'POST' }).catch(function() {});
  }

  function takeSample() {
    setStatus('Meting...');
    sampleBtn.disabled = true;
    fetch('/api/lux/sample', { method: 'POST' })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data.ok) {
          setStatus('Sample opgeslagen');
          if (luxValueEl) luxValueEl.textContent = data.lux.toFixed(1);
          if (brightnessValueEl) brightnessValueEl.textContent = data.brightness.toFixed(1);
        } else {
          setStatus(data.error || 'Fout');
        }
        sampleBtn.disabled = false;
      })
      .catch(function() { setStatus('Sample mislukt'); sampleBtn.disabled = false; });
  }



  function doAccept() {
    setStatus('Opslaan...');
    fetch('/api/lux/accept', { method: 'POST' })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data.ok) {
          hideAccept();
          if (fitResultEl && lastFitParams) {
            fitResultEl.textContent = 'Huidig: ' + formatParams(lastFitParams);
          }
          lastFitParams = null;
          if (sampleBtn) sampleBtn.disabled = false;
          fetchAndDraw();
          setStatus('Opgeslagen, seeds vernieuwd');
        } else {
          setStatus('Opslaan mislukt');
        }
      })
      .catch(function() { setStatus('Opslaan mislukt'); });
  }

  function doApprove() {
    setStatus('Fitting + opslaan...');
    fetch('/api/lux/fit', { method: 'POST' })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (!data.ok) throw new Error(data.error || 'Fit mislukt');
        return fetch('/api/lux/accept', { method: 'POST' })
          .then(function(r) { return r.json(); });
      })
      .then(function(data) {
        if (data.ok) {
          hideAccept();
          if (sampleBtn) sampleBtn.disabled = false;
          fetchAndDraw();
          setStatus('Opgeslagen, seeds vernieuwd');
        } else {
          setStatus('Opslaan mislukt');
        }
      })
      .catch(function(e) { setStatus(e.message || 'Approve mislukt'); });
  }

  function doClear() {
    if (!confirm('Wis samples?')) return;
    fetch('/api/lux/clear', { method: 'POST' })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        hideAccept();
        if (sampleBtn) sampleBtn.disabled = false;
        fetchAndDraw();
        setStatus('Samples gewist');
      })
      .catch(function() { setStatus('Wissen mislukt'); });
  }

  function doReset() {
    if (!confirm('Reset naar fabrieksinstellingen?')) return;
    fetch('/api/lux/reset', { method: 'POST' })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (fitResultEl) fitResultEl.textContent = '-';
        hideAccept();
        if (sampleBtn) sampleBtn.disabled = false;
        fetchAndDraw();
        setStatus('Reset naar defaults');
      })
      .catch(function() { setStatus('Reset mislukt'); });
  }

  function doDownload() {
    window.open('/api/lux/csv', '_blank');
  }

  // JS-side Gauss-Newton fit: y = B * (1 - exp(-r * lux))
  function jsFit(pts, initB, initR) {
    if (!pts || pts.length < 2) return null;
    var B = initB || 100, r = initR || 0.02;
    for (var iter = 0; iter < 12; iter++) {
      var jj00 = 0, jj01 = 0, jj11 = 0, jr0 = 0, jr1 = 0;
      for (var i = 0; i < pts.length; i++) {
        var lux = Math.max(pts[i].lux, 0);
        var obs = pts[i].bri;
        var e = 1 - Math.exp(-r * lux);
        var res = obs - B * e;
        var w = 1 / (1 + lux);
        var j0 = e, j1 = B * lux * (1 - e);
        jj00 += w * j0 * j0; jj01 += w * j0 * j1;
        jj11 += w * j1 * j1; jr0 += w * j0 * res; jr1 += w * j1 * res;
      }
      var det = jj00 * jj11 - jj01 * jj01;
      if (Math.abs(det) < 1e-20) break;
      var dB = (jj11 * jr0 - jj01 * jr1) / det;
      var dr = (-jj01 * jr0 + jj00 * jr1) / det;
      B += dB; r += dr;
      if (B < 10) B = 10; if (B > 500) B = 500;
      if (r < 0.001) r = 0.001; if (r > 0.5) r = 0.5;
      if (Math.abs(dB) < 1e-6 && Math.abs(dr) < 1e-6) break;
    }
    var ssRes = 0, ssTot = 0, meanY = 0;
    for (var j = 0; j < pts.length; j++) meanY += pts[j].bri;
    meanY /= pts.length;
    for (var k = 0; k < pts.length; k++) {
      var lk = Math.max(pts[k].lux, 0);
      var diff = pts[k].bri - B * (1 - Math.exp(-r * lk));
      ssRes += diff * diff;
      var dm = pts[k].bri - meanY;
      ssTot += dm * dm;
    }
    return { brMax: B, luxRate: r, r2: ssTot > 0 ? 1 - ssRes / ssTot : 0 };
  }

  function drawChart(data) {
    if (!chartCanvas) return;
    var ctx = chartCanvas.getContext('2d');
    var W = chartCanvas.width, H = chartCanvas.height;
    var pad = { l: 36, r: 10, t: 10, b: 32 };
    var pw = W - pad.l - pad.r, ph = H - pad.t - pad.b;

    ctx.clearRect(0, 0, W, H);

    // Determine axis ranges
    var xMax = data.luxMax || 300;
    var yMax = data.brMax || 100;
    // Expand yMax if any point exceeds it
    var pts = data.points || [];
    for (var i = 0; i < pts.length; i++) {
      if (pts[i].bri > yMax) yMax = pts[i].bri * 1.1;
    }

    // Quadratic X-axis: pixel = sqrt(lux/xMax) * pw, lux = (px/pw)² * xMax
    function luxToX(lux) { return Math.sqrt(lux / xMax) * pw; }
    function xToLux(px)  { var t = px / pw; return t * t * xMax; }

    // Grid lines + labels
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 0.5;
    ctx.fillStyle = '#666';
    ctx.font = '9px sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    var ySteps = 4;
    for (var j = 0; j <= ySteps; j++) {
      var yv = yMax * j / ySteps;
      var yp = pad.t + ph - (j / ySteps) * ph;
      ctx.beginPath(); ctx.moveTo(pad.l, yp); ctx.lineTo(pad.l + pw, yp); ctx.stroke();
      ctx.fillText(Math.round(yv), pad.l - 4, yp);
    }
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    var xSteps = 4;
    for (var k = 0; k <= xSteps; k++) {
      var xv = (k / xSteps) * (k / xSteps) * xMax;
      var xp = pad.l + (k / xSteps) * pw;
      ctx.beginPath(); ctx.moveTo(xp, pad.t); ctx.lineTo(xp, pad.t + ph); ctx.stroke();
      ctx.fillText(Math.round(xv), xp, pad.t + ph + 4);
    }

    // Axis labels
    ctx.fillStyle = '#888';
    ctx.textAlign = 'center';
    ctx.fillText('lux', pad.l + pw / 2, pad.t + ph + 20);
    ctx.save();
    ctx.translate(8, pad.t + ph / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('bri', 0, 0);
    ctx.restore();

    // Seeds-only fit (yellow) — the curve the seeds represent
    var seedBrMax = data.seedBrMax;
    var seedLuxRate = data.seedLuxRate;
    if (seedBrMax != null && seedLuxRate != null) {
      ctx.strokeStyle = '#fc0';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      for (var cx = 0; cx <= pw; cx++) {
        var lux = xToLux(cx);
        var bri = seedBrMax * (1.0 - Math.exp(-seedLuxRate * lux));
        var py = pad.t + ph - (bri / yMax) * ph;
        if (cx === 0) ctx.moveTo(pad.l + cx, py);
        else ctx.lineTo(pad.l + cx, py);
      }
      ctx.stroke();
    }

    // Live fit curve (green)
    if (data.fitBrMax != null && data.fitLuxRate != null) {
      ctx.strokeStyle = '#0c0';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      for (var cx2 = 0; cx2 <= pw; cx2++) {
        var lux2 = xToLux(cx2);
        var bri2 = data.fitBrMax * (1.0 - Math.exp(-data.fitLuxRate * lux2));
        var py2 = pad.t + ph - (bri2 / yMax) * ph;
        if (cx2 === 0) ctx.moveTo(pad.l + cx2, py2);
        else ctx.lineTo(pad.l + cx2, py2);
      }
      ctx.stroke();
    }

    // Draw points: seeds blue, samples red
    for (var p = 0; p < pts.length; p++) {
      var pt = pts[p];
      var px = pad.l + luxToX(pt.lux);
      var pyPt = pad.t + ph - (pt.bri / yMax) * ph;
      ctx.beginPath();
      ctx.arc(px, pyPt, pt.seed ? 3 : 4, 0, 2 * Math.PI);
      ctx.fillStyle = pt.seed ? '#48f' : '#f44';
      ctx.fill();
    }
  }

  function fetchAndDraw() {
    fetch('/api/lux/points').then(function(r) { return r.json(); })
      .then(function(data) {
        // Compute fits from data: seeds-only + all-points
        var pts = data.points || [];
        var seedCount = data.seedCount || 0;
        var seeds = pts.slice(0, seedCount);
        var sc = pts.length - seedCount;
        // Seeds-only fit → "old" row
        var seedFit = jsFit(seeds, data.brMax, data.luxRate);
        if (seedFit) {
          data.seedBrMax = seedFit.brMax;
          data.seedLuxRate = seedFit.luxRate;
          data.seedR2 = seedFit.r2;
        }
        // All-points fit → "new" row
        if (data.fitBrMax == null && pts.length >= 2) {
          var allFit = jsFit(pts, data.brMax, data.luxRate);
          if (allFit) { data.fitBrMax = allFit.brMax; data.fitLuxRate = allFit.luxRate; data.fitR2 = allFit.r2; }
        }
        drawChart(data);
        if (data.full && sampleBtn) sampleBtn.disabled = true;
        // Always show table: old + new(+N)
        if (fitResultEl) {
          var lm = data.luxMax ? Number(data.luxMax).toFixed(0) : '?';
          var ts = 'width:100%;font-size:0.75rem;color:#aaa;border-collapse:collapse';
          var html = '<table style="' + ts + '">';
          html += '<tr><th style="text-align:left;width:35%">0-' + lm + '</th>';
          html += '<th style="text-align:right;width:25%">brMax</th>';
          html += '<th style="text-align:right;width:22%">Slope</th>';
          html += '<th style="text-align:right;width:18%">R\u00b2</th></tr>';
          html += '<tr style="color:#fc0"><td>now</td>';
          html += '<td style="text-align:right">' + (data.seedBrMax != null ? Number(data.seedBrMax).toFixed(1) : '?') + '</td>';
          html += '<td style="text-align:right">' + (data.seedLuxRate != null ? Number(data.seedLuxRate).toFixed(4) : '?') + '</td>';
          html += '<td style="text-align:right"></td></tr>';
          if (data.fitBrMax != null) {
            html += '<tr style="color:#0c0"><td>new(+' + sc + ')</td>';
            html += '<td style="text-align:right">' + Number(data.fitBrMax).toFixed(1) + '</td>';
            html += '<td style="text-align:right">' + Number(data.fitLuxRate).toFixed(4) + '</td>';
            html += '<td style="text-align:right">' + Number(data.fitR2).toFixed(3) + '</td></tr>';
          }
          html += '</table>';
          fitResultEl.innerHTML = html;
        }
      })
      .catch(function() {});
  }

  function init() {
    sampleBtn       = document.getElementById('luxcal-sample');
    approveBtn      = document.getElementById('luxcal-approve');
    clearBtn        = document.getElementById('luxcal-clear');
    resetBtn        = document.getElementById('luxcal-reset');
    downloadBtn     = document.getElementById('luxcal-download');
    acceptBtn       = document.getElementById('luxcal-accept');
    statusEl        = document.getElementById('luxcal-status');
    luxValueEl      = document.getElementById('luxcal-lux');
    brightnessValueEl = document.getElementById('luxcal-bri');
    fitResultEl     = document.getElementById('luxcal-fitresult');
    newFitEl        = document.getElementById('luxcal-newfit');
    newParamsEl     = document.getElementById('luxcal-newparams');
    briSlider       = document.getElementById('luxcal-brightness');
    briLabel        = document.getElementById('luxcal-bri-num');
    chartCanvas     = document.getElementById('luxcal-chart');

    if (briSlider && briLabel) {
      briSlider.oninput = function() {
        briLabel.textContent = sliderToBrightness(parseInt(briSlider.value, 10)) + '%';
      };
      briSlider.onchange = function() {
        var bri = sliderToBrightness(parseInt(briSlider.value, 10));
        briLabel.textContent = bri + '%';
        fetch('/setBrightness?value=' + bri, { method: 'POST' }).catch(function() {});
      };
    }

    if (sampleBtn)   sampleBtn.onclick = takeSample;
    if (approveBtn)  approveBtn.onclick = doApprove;
    if (clearBtn)    clearBtn.onclick = doClear;
    if (resetBtn)    resetBtn.onclick = doReset;
    if (downloadBtn) downloadBtn.onclick = doDownload;
    if (acceptBtn)   acceptBtn.onclick = doAccept;

    // Disable sample button initially (mode off until modal opens)
    if (sampleBtn) sampleBtn.disabled = true;

    // SSE: update UI when firmware captures sample asynchronously
    Kwal.sse.onLuxcal(function(data) {
      if (luxValueEl) luxValueEl.textContent = data.lux.toFixed(1);
      if (brightnessValueEl) brightnessValueEl.textContent = data.brightness.toFixed(1);
      fetchAndDraw();
    });

    // SSE: auto-fit triggered by firmware — show accept UI
    Kwal.sse.onLuxcalFit(function(data) {
      lastFitParams = { brMax: data.brMax, luxRate: data.luxRate };
      if (sampleBtn) sampleBtn.disabled = true;
      fetchAndDraw();
      setStatus('Auto-fit \u2014 klik \u2713 om te accepteren');
    });
    // Early check: disable sun button if no lux sensor
    fetch('/api/lux/status').then(function(r) { return r.json(); })
      .then(function(data) {
        if (!data.hasLuxSensor) {
          var openBtn = document.getElementById('luxcal-open');
          if (openBtn) { openBtn.disabled = true; openBtn.style.opacity = '0.3'; }
        }
      }).catch(function() {});
  }

  return { init: init, loadStatus: loadStatus, onModalClose: onModalClose };
})();


// === js/log.js ===
/**
 * @file    log.js
 * @version 260312A
 * @date    2026-03-12
 *
 * Kwal - Log module
 */
(function() {
  'use strict';
  
  function fetchLog() {
    var pre = document.getElementById('log-content');
    if (!pre) return;
    
    fetch('/log')
      .then(function(r) { return r.text(); })
      .then(function(txt) { 
        pre.textContent = txt || '(empty)';
        pre.scrollTop = pre.scrollHeight;
      })
      .catch(function(e) { pre.textContent = 'Error: ' + e; });
  }
  
  function clearLog() {
    fetch('/log/clear')
      .then(function() { fetchLog(); })
      .catch(function(e) { console.error('Clear failed:', e); });
  }
  
  document.addEventListener('DOMContentLoaded', function() {
    var refreshBtn = document.getElementById('log-refresh');
    var clearBtn = document.getElementById('log-clear');
    
    if (refreshBtn) refreshBtn.onclick = fetchLog;
    if (clearBtn) clearBtn.onclick = clearLog;
    
    // Auto-fetch when modal opens
    var logModal = document.getElementById('log-modal');
    if (logModal) {
      var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) {
          if (m.attributeName === 'class' && 
              logModal.classList.contains('open')) {
            fetchLog();
          }
        });
      });
      observer.observe(logModal, { attributes: true });
    }
  });
})();


// === js/mp3grid.js ===
/**
 * @file    mp3grid.js
 * @version 260411D
 * @date    2026-04-11
 *
 * Kwal - MP3 Grid module
 * Canvas grid showing dirs from root_dirs index + theme box colors.
 * One-shot load via /api/audio/grid; crosshair follows SSE fragment events.
 */
Kwal.mp3grid = (function() {
  'use strict';

  var COLS = 101;   // file 1-100 (column 0 unused)
  var ROWS = 200;   // dir 1-199
  var CELL = 5;
  var W = COLS * CELL;
  var H = ROWS * CELL;

  var canvas, ctx, wrap;
  var dirSlider, fileSlider, dirVal, fileVal;
  var catpill, catlabel, closeBtn, playBtn, selLabel;

  var selRow = 0, selCol = 0;
  var loaded = false;

  // Data from /api/audio/grid
  var boxById = {};           // id → {name, color}
  var dirBox = null;          // Uint8Array[ROWS] dir → box id
  var dirFileCount = null;    // Uint16Array[ROWS] dir → number of files

  function hexToRgb(hex) {
    var h = hex.replace('#', '');
    if (h.length === 3) h = h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
    var n = parseInt(h, 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }

  function fmt3(n) { return String(n).padStart(3, '0'); }

  function draw() {
    if (!ctx || !loaded) return;

    // Base fill (dark)
    ctx.fillStyle = '#060619';
    ctx.fillRect(0, 0, W, H);

    // Per-dir: colored bar proportional to fileCount
    for (var r = 0; r < ROWS; r++) {
      var bid = dirBox[r];
      var box = bid ? boxById[bid] : null;
      var fc = dirFileCount[r];
      if (fc <= 0) continue;
      var y = r * CELL;
      var barW = Math.min(fc, COLS) * CELL;
      var rgb = box ? hexToRgb(box.color) : { r: 136, g: 136, b: 136 };

      // Fill bar: width proportional to fileCount (max COLS)
      ctx.fillStyle = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',0.35)';
      ctx.fillRect(0, y, barW, CELL);

      // Category line: 1px horizontal, same width as bar
      ctx.fillStyle = 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',0.95)';
      ctx.fillRect(0, y + 1, barW, 1);
    }

    // Vertical gridlines
    ctx.fillStyle = 'rgba(255,255,255,0.035)';
    for (var c = 1; c < COLS; c++) {
      ctx.fillRect(c * CELL, 0, 1, H);
    }

    // Row separators (black; white for selected row edges)
    for (var r = 0; r <= ROWS; r++) {
      var isSelEdge = (r === selRow) || (r === selRow + 1);
      ctx.fillStyle = isSelEdge ? '#ffffff' : '#000000';
      ctx.fillRect(0, r * CELL, W, 1);
    }

    // Selected column highlight
    ctx.fillStyle = 'rgba(255,225,64,0.55)';
    ctx.fillRect(selCol * CELL, 0, CELL, H);

    // Intersection cell: white
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(selCol * CELL, selRow * CELL, CELL, CELL);
  }

  function updateHeader() {
    if (dirVal) dirVal.textContent = fmt3(selRow);
    if (fileVal) fileVal.textContent = fmt3(selCol);
    var bid = (dirBox && selRow < ROWS) ? dirBox[selRow] : 0;
    var box = boxById[bid];
    if (catlabel) catlabel.textContent = box ? box.name : '-';
    if (catpill) catpill.style.background = box ? box.color : '#444';
    if (selLabel) selLabel.textContent = fmt3(selRow) + '/' + fmt3(selCol);
  }

  function keepRowVisible(row) {
    if (!wrap) return;
    var y = row * CELL;
    var viewTop = wrap.scrollTop;
    var viewH = wrap.clientHeight;
    var target = Math.max(0, y - Math.floor(viewH / 2));
    if (y < viewTop + CELL || y > viewTop + viewH - CELL) {
      wrap.scrollTop = target;
    }
  }

  function setSelection(row, col, scrollRow) {
    selRow = Math.max(0, Math.min(ROWS - 1, row | 0));
    selCol = Math.max(0, Math.min(COLS - 1, col | 0));
    if (dirSlider) dirSlider.value = selRow;
    if (fileSlider) fileSlider.value = selCol;
    updateHeader();
    if (scrollRow) keepRowVisible(selRow);
    draw();
  }

  function bindStepper(btn, deltaRow, deltaCol) {
    if (!btn) return;
    var timer = null, isDown = false;
    var step = function() { setSelection(selRow + deltaRow, selCol + deltaCol, !!deltaRow); };

    btn.addEventListener('pointerdown', function(e) {
      e.preventDefault();
      if (isDown) return;
      isDown = true;
      step();
      timer = setInterval(step, 130);
    });
    var stop = function() { isDown = false; if (timer) { clearInterval(timer); timer = null; } };
    btn.addEventListener('pointerup', stop);
    btn.addEventListener('pointercancel', stop);
    btn.addEventListener('pointerleave', stop);
    btn.addEventListener('click', function(e) { e.preventDefault(); });
  }

  function init() {
    canvas = document.getElementById('mg-grid');
    wrap = document.getElementById('mg-wrap');
    dirSlider = document.getElementById('mg-dir');
    fileSlider = document.getElementById('mg-file');
    dirVal = document.getElementById('mg-dir-val');
    fileVal = document.getElementById('mg-file-val');
    catpill = document.getElementById('mg-catpill');
    catlabel = document.getElementById('mg-catlabel');
    closeBtn = document.getElementById('mg-close');
    playBtn = document.getElementById('mg-play-btn');
    selLabel = document.getElementById('mg-sel-label');

    if (playBtn) {
      playBtn.addEventListener('click', function(e) {
        e.preventDefault();
        if (selRow > 0 && selCol > 0) {
          fetch('/api/audio/play?dir=' + selRow + '&file=' + selCol + '&src=grid%2Fsel').catch(function() {});
        }
      });
    }

    if (!canvas || !wrap) return;

    // HiDPI crisp canvas
    var dpr = Math.max(1, Math.floor(window.devicePixelRatio || 1));
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    canvas.width = W * dpr;
    canvas.height = H * dpr;
    ctx = canvas.getContext('2d', { alpha: false });
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // Slider events
    if (dirSlider) dirSlider.oninput = function() {
      setSelection(parseInt(dirSlider.value, 10) || 0, selCol, true);
    };
    if (fileSlider) fileSlider.oninput = function() {
      setSelection(selRow, parseInt(fileSlider.value, 10) || 0, false);
    };

    // Canvas tap
    canvas.addEventListener('pointerdown', function(e) {
      var rect = canvas.getBoundingClientRect();
      var x = Math.max(0, Math.min(W - 1, Math.floor(e.clientX - rect.left)));
      var y = Math.max(0, Math.min(H - 1, Math.floor(e.clientY - rect.top)));
      setSelection(Math.floor(y / CELL), Math.floor(x / CELL), true);
    });

    // Canvas double-tap: play file if tapped on file column, set dir theme if tapped on dir label
    canvas.addEventListener('dblclick', function(e) {
      e.preventDefault();
      if (selRow > 0 && selCol > 0) {
        fetch('/api/audio/play?dir=' + selRow + '&file=' + selCol + '&src=grid%2Ffile').catch(function() {});
      }
    });

    // Steppers
    bindStepper(document.getElementById('mg-dir-dec'), -1, 0);
    bindStepper(document.getElementById('mg-dir-inc'), 1, 0);
    bindStepper(document.getElementById('mg-file-dec'), 0, -1);
    bindStepper(document.getElementById('mg-file-inc'), 0, 1);

    // DIR label + value click: set single-dir theme_box
    var dirLabel = document.getElementById('mg-dir-label');
    var dirClickTargets = [dirVal, dirLabel];
    dirClickTargets.forEach(function(el) {
      if (!el) return;
      el.style.cursor = 'pointer';
      el.addEventListener('click', function(e) {
        e.preventDefault();
        if (selRow > 0) {
          fetch('/api/audio/themebox?dir=' + selRow).catch(function() {});
          if (dirVal) { dirVal.style.color = '#2ee88a'; setTimeout(function() { dirVal.style.color = ''; }, 400); }
        }
      });
    });

    // FILE label + value click: play that file
    var fileLabel = document.getElementById('mg-file-label');
    var fileClickTargets = [fileVal, fileLabel];
    fileClickTargets.forEach(function(el) {
      if (!el) return;
      el.style.cursor = 'pointer';
      el.addEventListener('click', function(e) {
        e.preventDefault();
        if (selRow > 0 && selCol > 0) {
          fetch('/api/audio/play?dir=' + selRow + '&file=' + selCol + '&src=grid%2Ffile').catch(function() {});
          if (fileVal) { fileVal.style.color = '#e8c72e'; setTimeout(function() { fileVal.style.color = ''; }, 400); }
        }
      });
    });
  }

  function load() {
    if (loaded) { draw(); return; }
    fetch('/api/audio/grid')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        boxById = {};
        dirBox = new Uint8Array(ROWS);
        dirFileCount = new Uint16Array(ROWS);

        if (data.boxes) {
          data.boxes.forEach(function(b) {
            boxById[b.id] = { name: b.name, color: b.color };
          });
        }
        if (data.dirs) {
          data.dirs.forEach(function(d) {
            if (d.d < ROWS) {
              dirBox[d.d] = d.b;
              dirFileCount[d.d] = d.n;
            }
          });
        }
        loaded = true;
        draw();
        updateHeader();
      })
      .catch(function(e) { console.error('[mp3grid] load failed:', e); });
  }

  function invalidate() {
    loaded = false;
  }

  function reload() {
    loaded = false;
    load();
  }

  return {
    init: init,
    load: load,
    reload: reload,
    invalidate: invalidate,
    setSelection: setSelection
  };
})();


// === js/sse.js ===
/**
 * @file    sse.js
 * @version 260312A
 * @date    2026-03-12
 *
 * Kwal - Server-Sent Events for live updates
 * Events: state, patterns, colors (legacy: fragment, light)
 */
(function() {
    'use strict';
    
    let eventSource = null;
    let reconnectTimer = null;
    let hasConnectedOnce = false;
    const RECONNECT_POLL_MS = 2000;
    
    // Callbacks registered by other modules
    const listeners = {
        state: [],      // New unified state event
        fragment: [],   // Legacy (still fired by firmware)
        light: [],      // Legacy (still fired by firmware)
        colors: [],
        patterns: [],
        luxcal: [],     // Lux calibration sample captured
        luxcalfit: [],  // Lux calibration fit results (auto or manual)
        reconnect: []   // Called on reconnect to refresh state
    };
    
    function connect() {
        if (eventSource) {
            eventSource.close();
        }
        
        eventSource = new EventSource('/api/events');
        
        eventSource.onopen = function() {
            console.log('[SSE] Connected');
            if (reconnectTimer) {
                clearTimeout(reconnectTimer);
                reconnectTimer = null;
            }
            // On reconnect (not first connect), refresh all data
            // ESP32 may have rebooted with new random pattern/color
            if (hasConnectedOnce) {
                console.log('[SSE] Reconnected - refreshing state');
                listeners.reconnect.forEach(function(cb) { cb(); });
            }
            hasConnectedOnce = true;
        };
        
        eventSource.onerror = function(e) {
            console.warn('[SSE] Error, reconnecting...', e);
            eventSource.close();
            eventSource = null;
            scheduleReconnect();
        };
        
        // Unified state event (new)
        eventSource.addEventListener('state', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] state:', data);
                listeners.state.forEach(cb => cb(data));
            } catch (err) {
                console.error('[SSE] state parse error:', err);
            }
        });
        
        // Fragment change event (legacy)
        eventSource.addEventListener('fragment', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] fragment:', data);
                listeners.fragment.forEach(cb => cb(data.dir, data.file, data.score));
            } catch (err) {
                console.error('[SSE] fragment parse error:', err);
            }
        });
        
        // Light change event (pattern/color)
        eventSource.addEventListener('light', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] light:', data);
                listeners.light.forEach(cb => cb(data.pattern, data.color));
            } catch (err) {
                console.error('[SSE] light parse error:', err);
            }
        });
        
        // Colors list change event
        eventSource.addEventListener('colors', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] colors:', data);
                listeners.colors.forEach(cb => cb(data));
            } catch (err) {
                console.error('[SSE] colors parse error:', err);
            }
        });
        
        // Patterns list change event
        eventSource.addEventListener('patterns', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] patterns:', data);
                listeners.patterns.forEach(cb => cb(data));
            } catch (err) {
                console.error('[SSE] patterns parse error:', err);
            }
        });

        // Lux calibration sample captured
        eventSource.addEventListener('luxcal', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] luxcal:', data);
                listeners.luxcal.forEach(cb => cb(data));
            } catch (err) {
                console.error('[SSE] luxcal parse error:', err);
            }
        });

        // Lux calibration fit results (auto-fit or manual)
        eventSource.addEventListener('luxcalfit', function(e) {
            try {
                const data = JSON.parse(e.data);
                console.log('[SSE] luxcalfit:', data);
                listeners.luxcalfit.forEach(cb => cb(data));
            } catch (err) {
                console.error('[SSE] luxcalfit parse error:', err);
            }
        });
    }
    
    function scheduleReconnect() {
        if (reconnectTimer) return;
        console.log('[SSE] Starting reconnect polling...');
        reconnectTimer = setInterval(async function() {
            try {
                const response = await fetch('/api/health');
                if (response.ok) {
                    console.log('[SSE] Device back online, reloading page...');
                    clearInterval(reconnectTimer);
                    reconnectTimer = null;
                    location.reload();
                }
            } catch (e) {
                // Still offline, keep polling
            }
        }, RECONNECT_POLL_MS);
    }
    
    function disconnect() {
        if (reconnectTimer) {
            clearInterval(reconnectTimer);
            reconnectTimer = null;
        }
        if (eventSource) {
            eventSource.close();
            eventSource = null;
        }
    }
    
    /**
     * Register callback for fragment changes
     * @param {function(dir: number, file: number): void} cb
     */
    function onFragment(cb) {
        if (typeof cb === 'function') {
            listeners.fragment.push(cb);
        }
    }
    
    /**
     * Register callback for light changes
     * @param {function(patternId: string, colorId: string): void} cb
     */
    function onLight(cb) {
        if (typeof cb === 'function') {
            listeners.light.push(cb);
        }
    }
    
    /**
     * Register callback for colors list changes
     * @param {function(data: object): void} cb
     */
    function onColors(cb) {
        if (typeof cb === 'function') {
            listeners.colors.push(cb);
        }
    }
    
    /**
     * Register callback for patterns list changes
     * @param {function(data: object): void} cb
     */
    function onPatterns(cb) {
        if (typeof cb === 'function') {
            listeners.patterns.push(cb);
        }
    }

    /**
     * Register callback for lux calibration sample events
     * @param {function(data: {n: number, lux: number, brightness: number}): void} cb
     */
    function onLuxcal(cb) {
        if (typeof cb === 'function') {
            listeners.luxcal.push(cb);
        }
    }

    /**
     * Register callback for lux calibration fit result events
     * @param {function(data: object): void} cb
     */
    function onLuxcalFit(cb) {
        if (typeof cb === 'function') {
            listeners.luxcalfit.push(cb);
        }
    }
    
    /**
     * Register callback for reconnect (to refresh state after ESP32 reboot)
     * @param {function(): void} cb
     */
    function onReconnect(cb) {
        if (typeof cb === 'function') {
            listeners.reconnect.push(cb);
        }
    }
    
    /**
     * Register callback for unified state event
     * @param {function(data: {brightness, audioLevel, patternId, patternLabel, colorId, colorLabel, fragment}): void} cb
     */
    function onState(cb) {
        if (typeof cb === 'function') {
            listeners.state.push(cb);
        }
    }
    
    // Export
    Kwal.sse = {
        connect: connect,
        disconnect: disconnect,
        onState: onState,
        onFragment: onFragment,
        onLight: onLight,
        onColors: onColors,
        onPatterns: onPatterns,
        onLuxcal: onLuxcal,
        onLuxcalFit: onLuxcalFit,
        onReconnect: onReconnect
    };
})();


